starter.versions.tf:
terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

starter.variables.tf:
variable "lb_arn" {
  description = "Input variable lb_arn."
  type        = string
}

variable "target_group_arn" {
  description = "Input variable target_group_arn."
  type        = string
}

variable "certificate_arn" {
  description = "Input variable certificate_arn."
  type        = string
}

variable "aws_region" {
  description = "Input variable aws_region."
  type        = string
  default     = "us-east-1"
}

starter.main.tf:
provider "aws" {
  region = var.aws_region
}

resource "aws_lb_listener" "https" {
  # TODO - Complete the graded block.
  # Complete this block using the challenge requirements.
}

resource "aws_lb_listener" "http" {
  port              = 80
  protocol          = "HTTP"
  load_balancer_arn = var.lb_arn
  default_action {
    type = "redirect"
    redirect {
      port        = "443"
      protocol    = "HTTPS"
      status_code = "HTTP_301"
    }
  }
}
